270→// --- Attribution math ---
271→function calcCredits(model, tps, halfLife, customW) {
272→  const n = tps.length;
273→  if (n === 0) return [];
274→  if (n === 1) return [1];
275→
276→  switch (model) {
277→    case 'first-touch': {
278→      const c = Array(n).fill(0);
279→      c[0] = 1;
280→      return c;
281→    }
282→    case 'last-touch': {
283→      const c = Array(n).fill(0);
284→      c[n - 1] = 1;
285→      return c;
286→    }
287→    case 'linear': {
288→      return Array(n).fill(1 / n);
289→    }
290→    case 'time-decay': {
291→      const maxDay = tps[n - 1].days;
292→      const rawDecay = tps.map(function(tp) {
293→        const daysBeforeConversion = maxDay - tp.days;
294→        return Math.pow(2, -daysBeforeConversion / halfLife);
295→      });
296→      const sum = rawDecay.reduce(function(a, b) { return a + b; }, 0);
297→      return rawDecay.map(function(v) { return v / sum; });
298→    }
299→    case 'u-shaped': {
300→      const c = Array(n).fill(0);
301→      if (n === 2) return [0.5, 0.5];
302→      c[0] = 0.4;
303→      c[n - 1] = 0.4;
304→      const mid = 0.2 / (n - 2);
305→      for (let i = 1; i < n - 1; i++) c[i] = mid;
306→      return c;
307→    }
308→    case 'w-shaped': {
309→      const c = Array(n).fill(0);
310→      if (n === 2) return [0.5, 0.5];
311→      if (n === 3) return [0.333, 0.334, 0.333];
312→      const midIdx = Math.floor(n / 2);
313→      c[0] = 0.3;
314→      c[midIdx] = 0.3;
315→      c[n - 1] = 0.3;
316→      let others = n - 3;
317→      if (others <= 0) {
318→        const s = c.reduce(function(a, b) { return a + b; }, 0);
319→        return c.map(function(v) { return v / s; });
320→      }
321→      const each = 0.1 / others;
322→      for (let i = 0; i < n; i++) {
323→        if (i !== 0 && i !== midIdx && i !== n - 1) c[i] = each;
324→      }
325→      return c;
326→    }
327→    case 'custom': {
328→      if (!customW || customW.length !== n) return Array(n).fill(1 / n);
329→      const sum = customW.reduce(function(a, b) { return a + b; }, 0);
330→      if (sum === 0) return Array(n).fill(1 / n);
331→      return customW.map(function(w) { return w / sum; });
332→    }
333→    default: return Array(n).fill(1 / n);
334→  }
335→}
