337→function calcAllModels(tps, halfLife, customW) {
338→  var models = ['first-touch', 'last-touch', 'linear', 'time-decay', 'u-shaped', 'w-shaped'];
339→  var result = {};
340→  for (var i = 0; i < models.length; i++) {
341→    result[models[i]] = calcCredits(models[i], tps, halfLife, customW);
342→  }
343→  return result;
344→}
