349→function makeEl(tag, attrs, children) {
350→  var el = document.createElement(tag);
351→  if (attrs) {
352→    Object.keys(attrs).forEach(function(k) {
353→      if (k === 'style' && typeof attrs[k] === 'object') {
354→        Object.assign(el.style, attrs[k]);
355→      } else if (k.startsWith('on')) {
356→        el.addEventListener(k.slice(2), attrs[k]);
357→      } else if (k === 'className') {
358→        el.className = attrs[k];
359→      } else {
360→        el.setAttribute(k, attrs[k]);
361→      }
362→    });
363→  }
364→  if (children) {
365→    if (typeof children === 'string') {
366→      el.textContent = children;
367→    } else if (Array.isArray(children)) {
368→      children.forEach(function(c) { if (c) el.appendChild(c); });
