538→function renderCustomWeights() {
539→  var section = document.getElementById('custom-section');
540→  var container = document.getElementById('custom-weights');
541→  if (state.model !== 'custom') {
542→    section.classList.add('hidden');
543→    return;
544→  }
545→  section.classList.remove('hidden');
546→  clearEl(container);
547→
548→  while (state.customWeights.length < state.touchpoints.length) state.customWeights.push(1);
549→  while (state.customWeights.length > state.touchpoints.length) state.customWeights.pop();
550→
551→  state.touchpoints.forEach(function(tp, i) {
