553→    var label = makeEl('span', { style: { fontSize: '0.75rem', flex: '1', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' } }, tp.name);
554→    var input = makeEl('input', { type: 'number', min: '0', max: '100', value: String(state.customWeights[i]), style: { width: '55px' } });
555→    (function(idx) {
556→      input.addEventListener('change', function() {
557→        state.customWeights[idx] = parseFloat(this.value) || 0;
558→        updateAll();
559→      });
560→    })(i);
561→
562→    var row = makeEl('div', { style: { display: 'flex', alignItems: 'center', gap: '6px', marginBottom: '4px' } }, [dot, label, input]);
563→    container.appendChild(row);
564→  });
