567→function renderPrompt() {
568→  var el = document.getElementById('prompt-output');
569→  var credits = calcCredits(state.model, state.touchpoints, state.decayHalfLife, state.customWeights);
570→  var info = MODEL_INFO[state.model];
571→  var n = state.touchpoints.length;
572→
573→  if (n === 0) {
574→    el.textContent = 'Add touchpoints to generate a prompt.';
575→    return;
576→  }
577→
578→  var sorted = credits
579→    .map(function(c, i) { return { name: state.touchpoints[i].name, credit: c }; })
580→    .sort(function(a, b) { return b.credit - a.credit; });
581→
582→  var top = sorted[0];
583→  var bottom = sorted[sorted.length - 1];
584→  var journey = state.touchpoints.map(function(tp) { return tp.name; }).join(' -> ');
585→
586→  var parts = [];
587→  parts.push("I'm analyzing a " + n + "-step customer journey using the " + info.short + " attribution model.");
588→  parts.push("\nJourney: " + journey);
589→  parts.push("\nCredit distribution:");
590→  sorted.forEach(function(s) {
591→    parts.push("  " + s.name + ": " + (s.credit * 100).toFixed(1) + "%");
592→  });
593→
594→  if (state.model === 'time-decay') {
595→    parts.push("\nDecay half-life: " + state.decayHalfLife + " days");
596→  }
597→
598→  parts.push("\nThe " + info.short + " model " + (top.credit > 0.5 ? 'heavily favors' : 'gives the most credit to') + ' "' + top.name + '" (' + (top.credit * 100).toFixed(1) + '%).');
599→
600→  if (n > 2) {
601→    parts.push('"' + bottom.name + '" gets the least credit at ' + (bottom.credit * 100).toFixed(1) + '%.');
602→  }
603→
604→  parts.push("\nHelp me understand: Is " + info.short + " the right model for this journey? What would change if I used a different model? Which touchpoints might be over- or under-valued?");
605→
606→  el.textContent = parts.join('\n');
607→}
